<?php $e=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$a=function($f){return $f?base_url().'upload/qms_report_assets/'.rawurlencode(basename($f)):'';};$risk=array();$opp=array();foreach($entries as $x){if($x->item_type==='Opportunity')$opp[]=$x;else$risk[]=$x;}?><!doctype html><html><head><meta charset="utf-8"><title>Monitoring &amp; Review</title><style>@page{size:landscape;margin:12mm}body{font-family:Arial;font-size:10px}.bar{margin-bottom:8px}.head{width:100%;max-height:90px;object-fit:contain}.title{text-align:center;font-size:20px;font-weight:bold;margin:8px}.meta{font-size:13px;margin-bottom:4px}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border:1px solid #111;padding:5px;vertical-align:top;word-wrap:break-word}th{background:#8eafd5;text-align:center;font-size:12px}.sub{background:#c7d8eb}.section{font-size:13px;font-weight:bold}.check{text-align:center}.foot{width:100%;max-height:60px;object-fit:contain;margin-top:12px}.sign{display:flex;justify-content:space-around;margin-top:42px;font-size:13px}.line{border-top:1px solid;margin-top:42px;text-align:center;padding-top:3px}@media print{.bar{display:none}}</style></head><body><div class="bar"><button onclick="window.print()">Print / Save PDF</button></div><?php if($settings&&$settings->letterhead_file):?><img class="head" src="<?=$e($a($settings->letterhead_file))?>"><?php endif;?><div class="title">RISK &amp; OPPORTUNITY MONITORING &amp; REVIEW FORM</div><div class="meta"><i>Bureau/Service/Functional Division/School:</i> <?=$e($sectionName)?><br><i>Date of Monitoring:</i> <?=$monitoringDate?$e($monitoringDate):''?></div><table><colgroup><col style="width:26%"><col style="width:9%"><col style="width:9%"><col style="width:4%"><col style="width:4%"><col style="width:4%"><col style="width:17%"><col style="width:27%"></colgroup><tr><th rowspan="2">DECLARED PROCESS<br>&amp; RISK DESCRIPTION/<br>OPPORTUNITY STATEMENT</th><th colspan="2">RISK/OPPORTUNITY RATING</th><th colspan="3">RISK/ OPPORTUNITY STATUS</th><th rowspan="2">EXPLANATION</th><th rowspan="2">RECOMMENDATION OF THE RMT</th></tr><tr><th class="sub">Before</th><th class="sub">After</th><th class="sub">Increased</th><th class="sub">Reduced</th><th class="sub">Recurring</th></tr><?php foreach(array('RISK'=>$risk,'OPPORTUNITY'=>$opp) as $label=>$rows):?><tr><td class="section"><?=$label?></td><?php for($i=0;$i<7;$i++):?><td></td><?php endfor;?></tr><?php foreach($rows as $x):?><tr><td><?=$e($x->statement)?></td><td class="check"><?=$x->before_rating?></td><td class="check"><?=$x->after_rating?></td><td class="check"><?=$x->status==='Increased'?'✓':''?></td><td class="check"><?=$x->status==='Reduced'?'✓':''?></td><td class="check"><?=$x->status==='Recurring'?'✓':''?></td><td><?=$e($x->explanation)?></td><td><?=$e($x->recommendation)?></td></tr><?php endforeach;endforeach;?></table><div class="sign"><div>Monitored by:<div class="line"><?=$e($settings&&isset($settings->monitored_by)?$settings->monitored_by:'')?><br>Member, RMT</div></div><div>Reviewed by:<div class="line"><?=$e($settings&&isset($settings->reviewed_by)?$settings->reviewed_by:'')?><br>Lead, RMT</div></div><div>Acknowledged by:<div class="line"><?=$e($settings&&isset($settings->acknowledged_by)?$settings->acknowledged_by:'')?><br>Process Holder</div></div></div><?php if($settings&&$settings->footer_file):?><img class="foot" src="<?=$e($a($settings->footer_file))?>"><?php endif;?></body></html>
